-- WezTerm on Windows, mirroring kitty.conf. bootstrap-wsl.sh copies this to %USERPROFILE%\.wezterm.lua.
local wezterm = require 'wezterm'
local act = wezterm.action
local config = wezterm.config_builder()

-- bootstrap-wsl.sh fills in the distro name ($WSL_DISTRO_NAME)
config.default_domain = 'WSL:__WSL_DISTRO__'

config.font = wezterm.font 'CaskaydiaCove Nerd Font'
config.font_size = 12.0

-- BEGIN kitty colors (generated by ~/.config/dotfiles/kitty-to-wezterm.sh, don't edit by hand)
config.colors = {
  foreground = '#f1dfda',
  background = '#1a110f',
  cursor_bg = '#f1dfda',
  cursor_border = '#f1dfda',
  cursor_fg = '#d8c2bc',
  selection_fg = '#442a23',
  selection_bg = '#e7bdb3',
  ansi = { '#1a110f', '#ff7672', '#98ff7f', '#ffe572', '#f29d87', '#723524', '#ffb5a1', '#fff3ef', },
  brights = { '#47413f', '#ffa19f', '#b7ffa5', '#ffeea5', '#ffc0af', '#ffcbbd', '#ffddd4', '#fffaf8', },
  tab_bar = {
    background = '#1a110f',
    active_tab = { bg_color = '#ffb5a1', fg_color = '#561f10', intensity = 'Bold' },
    inactive_tab = { bg_color = '#1a110f', fg_color = '#d8c2bc' },
    new_tab = { bg_color = '#1a110f', fg_color = '#d8c2bc' },
  },
}
-- END kitty colors

config.window_padding = { left = 12, right = 12, top = 12, bottom = 12 }
config.window_background_opacity = 0.8
config.win32_system_backdrop = 'Acrylic'
config.window_decorations = 'RESIZE'

config.default_cursor_style = 'BlinkingBlock'
config.scrollback_lines = 3000
config.use_fancy_tab_bar = false
config.hide_tab_bar_if_only_one_tab = true

config.keys = {
  { key = 'n', mods = 'CTRL|SHIFT', action = act.SpawnWindow },
  { key = 't', mods = 'CTRL', action = act.SpawnTab 'DefaultDomain' },
  { key = '=', mods = 'CTRL', action = act.IncreaseFontSize },
  { key = '-', mods = 'CTRL', action = act.DecreaseFontSize },
  { key = '0', mods = 'CTRL', action = act.ResetFontSize },
}
for i = 1, 9 do
  table.insert(config.keys, { key = tostring(i), mods = 'ALT', action = act.ActivateTab(i - 1) })
end

return config
